CREATE SCHEMA IF NOT EXISTS "public";
CREATE TYPE "WorkspaceRole" AS ENUM ('OWNER','ADMIN','EDITOR','VIEWER');
CREATE TYPE "InvitationStatus" AS ENUM ('PENDING','ACCEPTED','DECLINED','CANCELLED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"avatarUrl" TEXT,"lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Workspace" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"description" TEXT,"iconUrl" TEXT,"createdById" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "WorkspaceMember" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"role" "WorkspaceRole" NOT NULL DEFAULT 'VIEWER',"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("workspaceId","userId"));
CREATE TABLE "Invitation" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"recipientId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"senderId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"role" "WorkspaceRole" NOT NULL DEFAULT 'VIEWER',"status" "InvitationStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"respondedAt" TIMESTAMP(3),UNIQUE("workspaceId","recipientId"));
CREATE TABLE "Folder" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"parentId" TEXT REFERENCES "Folder"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("workspaceId","parentId","name"));
CREATE TABLE "File" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"folderId" TEXT REFERENCES "Folder"("id") ON DELETE SET NULL,"name" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"storageKey" TEXT NOT NULL UNIQUE,"uploadedById" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"lastModifiedById" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("workspaceId","folderId","name"));
CREATE TABLE "ActivityLog" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"actorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"entityName" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "WorkspaceMember_userId_idx" ON "WorkspaceMember"("userId"); CREATE INDEX "Invitation_recipientId_status_idx" ON "Invitation"("recipientId","status"); CREATE INDEX "Folder_workspaceId_parentId_idx" ON "Folder"("workspaceId","parentId"); CREATE INDEX "File_workspaceId_folderId_idx" ON "File"("workspaceId","folderId"); CREATE INDEX "ActivityLog_workspaceId_createdAt_idx" ON "ActivityLog"("workspaceId","createdAt");
